import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';
import {log} from '../../shared/logger.js';

jest.mock('../../shared/logger.js', () => ({
  log: {
    info: jest.fn(),
    warn: jest.fn(),
    error: jest.fn(),
    debug: jest.fn(),
  },
}));

describe('ToolRegistry', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('registers a tool requiring a location string, rejects empty input, and does not call executor ([validated by specs/hal-engine-tool-input-validation/spec.md])', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn().mockResolvedValue('ok');
    registry.register(
      {
        name: 'get_weather',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      executor as any
    );

    const response = await registry.execute('get_weather', {});

    expect(response.result).toMatch(/location/);
    expect(response.result).toMatch(/required/i);
    expect(executor).not.toHaveBeenCalled();
  });

  it('passes through extra properties unchanged ([validated by specs/hal-engine-tool-input-validation/spec.md])', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn().mockResolvedValue('ok');
    registry.register(
      {
        name: 'echo',
        description: 'test',
        inputSchema: {type: 'object', properties: {}},
      },
      executor as any
    );

    const input = {foo: 'bar', extra: 123};
    await registry.execute('echo', input);

    expect(executor).toHaveBeenCalledTimes(1);
    expect(executor).toHaveBeenCalledWith(input, undefined);
  });

  it('rejects wrong-typed fields naming the path and expected type but not the value ([validated by specs/hal-engine-tool-input-validation/spec.md])', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn().mockResolvedValue('ok');
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {age: {type: 'number'}},
        },
      },
      executor as any
    );

    const secretValue = 'SECRET_999';
    const response = await registry.execute('test_tool', {age: secretValue} as any);

    expect(response.result).toMatch(/age/);
    expect(response.result).toMatch(/number/);
    expect(response.result).not.toContain(secretValue);
    expect(executor).not.toHaveBeenCalled();
  });

  it('throws at registration time naming the tool for an uncompilable schema ([validated by specs/hal-engine-tool-input-validation/spec.md])', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('validates against the current schema for function-valued tool definitions ([validated by specs/hal-engine-tool-input-validation/spec.md])', async () => {
    const registry = new ToolRegistry();
    let requiredField = 'first';
    const executor = jest.fn().mockResolvedValue('ok');

    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {[requiredField]: {type: 'string'}},
          required: [requiredField],
        },
      }),
      executor as any
    );

    // First call requires 'first'
    const res1 = await registry.execute('dynamic_tool', {first: 'hi'});
    expect(res1.result).toBe('ok');

    // Change requirement
    requiredField = 'second';
    const res2 = await registry.execute('dynamic_tool', {first: 'hi'});
    expect(res2.result).toMatch(/second/);
    expect(res2.result).toMatch(/required/i);
  });

  it('compiles a static tool schema only once across multiple calls ([validated by specs/hal-engine-tool-input-validation/spec.md])', async () => {
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'static_tool',
        description: 'test',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async () => 'ok'
    );

    const initialCompileCount = compileSpy.mock.calls.length;

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {a: 'val'});
    }

    expect(compileSpy).toHaveBeenCalledTimes(initialCompileCount);
    compileSpy.mockRestore();
  });

  it('still throws Unknown tool for unregistered names ([validated by specs/hal-engine-tool-input-validation/spec.md])', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('nope', {})).rejects.toThrow(/Unknown tool: nope/);
  });

  it('does not log or return rejected property values ([validated by specs/hal-engine-tool-input-validation/spec.md])', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'secure_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {password: {type: 'string', minLength: 10}},
        },
      },
      async () => 'ok'
    );

    const secretPassword = 'SHORT';
    const response = await registry.execute('secure_tool', {password: secretPassword});

    expect(response.result).not.toContain(secretPassword);

    const warnCalls = (log.warn as jest.Mock).mock.calls;
    const allLoggedData = JSON.stringify(warnCalls);
    expect(allLoggedData).not.toContain(secretPassword);
  });
});

